function normalizeResources(model){for(const a of model.apps){a.documents=(a.documents||[]).map(d=>({...d,title:typeof d.title==='string'?{en:d.title,tr:d.title}:d.title}));a.images=(a.images||[]).map((r,i)=>typeof r==='string'?{id:a.id+'-image-'+i,url:r,caption:{}}:r)}return model}
let data=normalizeResources(structuredClone(bridge.bootstrap.data));
for(const a of data.apps){const m=PREVIEW_META[a.id]||{labels:[],comments:[],featuredComment:null};a.labels??=structuredClone(m.labels);a.comments??=structuredClone(m.comments);if(a.featuredComment===undefined)a.featuredComment=m.featuredComment}
for(const a of data.apps){a.archived??=false;a.featured??=['pa','servis','bizpuan'].includes(a.id);a.links??=a.platforms.map((platform,i)=>({id:a.id+'-link-'+i,platform,version:a.version,url:a.url||'',pending:!a.url,label:{en:a.en.name+' for '+platform,tr:platform+' için '+a.tr.name}}));a.documents??=[];a.images??=[];a.symbol??=(a.en.name||'A').split(' ').map(x=>x[0]).slice(0,2).join('');}
data.filters??={category:true,platform:true,label:true,sort:true,defaultSort:'default'};data.uiOverrides??={en:{},tr:{}};data.activity??=[];data.admins??=[];data.adminAssignments??=data.admins.map(id=>({employeeId:id==='zeynep'?'10002':'10001',profileId:id}));
function acceptServer(response){bridge.bootstrap=response;data=normalizeResources(structuredClone(response.data));personal[state.person.id]=structuredClone(response.personal)}
let prefs={lang:'en',theme:'light'};try{prefs={...prefs,...JSON.parse(localStorage.getItem('arcelik-review-prefs')||'{}')}}catch{}
if(!['en','tr'].includes(prefs.lang))prefs.lang='en';if(!['light','dark'].includes(prefs.theme))prefs.theme='light';
const isAdmin=()=>innerWidth>=900&&bridge.bootstrap.isAdmin;
let state={lang:prefs.lang,theme:prefs.theme,person:bridge.bootstrap.profile,view:'store',tab:'arcelik',category:'all',expanded:null,query:'',platform:'all',label:'all',sort:data.filters.defaultSort,adminStatus:'all',adminQuery:'',translationQuery:'',bulk:[],filtersOpen:null,commentDrafts:{},layout:(innerWidth<=680?(prefs.layoutMobile==='compare'?'compare':'cards'):(prefs.layoutDesktop==='compare'?'compare':'cards')),narrowLayout:innerWidth<=680,categoryMenuOpen:null,selected:null,account:false,adminTab:'dashboard',suggestionIndex:-1,searchOpen:false,rotation:0};
let previousScroll=window.scrollY,toastTimer,editorInitial='',editorContext=null,closingMobile=false,lastFocus=null;
const t=key=>data.uiOverrides[state.lang]?.[key]||TEXT[state.lang][key]||key;
const local=app=>({name:app[state.lang]?.name?.trim()||app[state.lang==='en'?'tr':'en']?.name||t('unnamedApp'),summary:(app[state.lang]?.description?.trim()||app[state.lang]?.summary?.trim()||t('translationMissing')).slice(0,150),description:(app[state.lang]?.description?.trim()||app[state.lang]?.summary?.trim()||t('translationMissing')).slice(0,150)});
const catName=id=>data.categories.find(c=>c.id===id)?.[state.lang]||id;
const isMobile=()=>innerWidth<900;
const appById=id=>data.apps.find(a=>a.id===id);
const appList=()=>data.apps.filter(a=>a.active&&!a.archived);

data.uiLayout??={columns:3,appOrder:[],featuredOrder:[],webOrder:[],webSizes:{connecta:'wide'}};
function ordered(items,ids=[]){const rank=new Map(ids.map((id,i)=>[id,i]));return [...items].sort((a,b)=>(rank.get(a.id)??9999)-(rank.get(b.id)??9999))}
function layoutRows(items,key,sizes=false){return '<div class="layout-rows" data-layout-list="'+key+'">'+ordered(items,data.uiLayout[key]||[]).map(r=>'<div class="layout-row" data-order-id="'+r.id+'"><input type="hidden" name="order-'+key+'" value="'+r.id+'"><span>'+esc(r._app?local(r).name:r.en&&r.tr?r[state.lang].name:r.name)+'</span>'+(sizes?'<select name="size-'+r.id+'" aria-label="'+wx('Card size','Kart boyutu')+'">'+[['normal','Standard','Standart'],['wide','Wide','Geniş'],['compact','Compact','Küçük']].map(([id,en,tr])=>'<option value="'+id+'"'+((data.uiLayout.webSizes[r.id]||'normal')===id?' selected':'')+'>'+wx(en,tr)+'</option>').join('')+'</select>':'')+'<button type="button" class="layout-move" data-layout-move="up" aria-label="'+wx('Move up','Yukarı taşı')+'">↑</button><button type="button" class="layout-move" data-layout-move="down" aria-label="'+wx('Move down','Aşağı taşı')+'">↓</button></div>').join('')+'</div>'}
state.multi={category:[],platform:[],label:[]};
const results=()=>{const list=appList().filter(a=>(!state.multi.category.length||state.multi.category.some(v=>a.categories.includes(v)))&&(!state.multi.platform.length||state.multi.platform.some(v=>a.platforms.includes(v)))&&(!state.multi.label.length||state.multi.label.some(v=>(a.labels||[]).includes(v)))&&(state.category==='all'||a.categories.includes(state.category))&&(state.platform==='all'||a.platforms.includes(state.platform))&&(state.label==='all'||(a.labels||[]).includes(state.label))&&(!state.query.trim()||(local(a).name+' '+local(a).description+' '+a.categories.map(catName).join(' ')).toLocaleLowerCase(state.lang).includes(state.query.trim().toLocaleLowerCase(state.lang))));if(state.sort!=='default')list.sort((a,b)=>local(a).name.localeCompare(local(b).name,state.lang)*(state.sort==='za'?-1:1));return state.sort==='default'?ordered(list,data.uiLayout.appOrder):list};
const labelInfo=id=>LABELS.find(l=>l.id===id);
const labelName=id=>labelInfo(id)?.[state.lang]||id;
function labelsMarkup(a){return '<div class="app-labels">'+(a.labels||[]).map(id=>'<span class="app-label" style="--label-color:'+esc(labelInfo(id)?.color||'#3969c4')+'">'+esc(labelName(id))+'</span>').join('')+'</div>'}
function commentText(c){return typeof c.text==='string'?c.text:c.text[state.lang]||c.text[c.language]||Object.values(c.text)[0]||''}
function featuredMarkup(a){const c=(a.comments||[]).find(c=>c.id===a.featuredComment);return c?'<blockquote class="card-comment" data-featured-id="'+esc(c.id)+'"><span class="quote-mark" aria-hidden="true">❝</span><span>'+esc(commentText(c))+'</span></blockquote>':''}

function commentDate(c){return new Date(c.time).toLocaleString(state.lang==='tr'?'tr-TR':'en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Istanbul'})}
function commentRow(a,c){const featured=a.featuredComment===c.id;return '<article class="comment-row '+(featured?'is-featured':'')+'"><div class="comment-by"><b>'+esc(c.author)+'</b><time datetime="'+esc(c.time)+'">'+esc(commentDate(c))+'</time></div><p>'+esc(commentText(c))+'</p>'+(c.language&&c.language!==state.lang?'<small class="muted">'+t('originalComment')+': '+c.language.toUpperCase()+'</small>':'')+'<div class="comment-actions">'+(featured?'<span class="featured-label">'+t('featuredComment')+'</span>':'')+(isAdmin()?'<button class="btn" data-feature-comment="'+esc(c.id)+'" data-app="'+a.id+'">'+t(featured?'unfeatureComment':'featureComment')+'</button>':'')+'</div></article>'}
function commentsMarkup(a){const draft=state.commentDrafts[a.id]?.text||'';return '<section class="comments-section" aria-label="'+esc(t('comments'))+'"><h3>'+t('comments')+' <span class="pill">'+a.comments.length+'</span></h3><div class="comment-list">'+(a.comments.length?a.comments.map(c=>commentRow(a,c)).join(''):'<p class="detail-desc">'+t('noComments')+'</p>')+'</div><form class="comment-form" novalidate data-app="'+a.id+'"><label class="field">'+t('writeComment')+'<textarea name="comment" data-comment="'+a.id+'" maxlength="300" required rows="3">'+esc(draft)+'</textarea></label><div class="comment-meta"><span>'+t('postingAs')+' <b>'+state.person.name+'</b></span><span class="comment-counter">'+draft.length+'/300</span></div><p class="comment-notice">'+t('commentNotice')+'</p><button type="submit" class="btn primary">'+t('postComment')+'</button></form></section>'}
function refreshView(){const y=window.scrollY,pane=$('detail-pane'),paneTop=pane?.scrollTop||0,mobile=$('mobileDetail'),mobileTop=mobile.scrollTop;render();if(pane&&$('detail-pane'))$('detail-pane').scrollTop=paneTop;if(mobile.open&&state.selected){mobile.innerHTML=detailMarkup(appById(state.selected),true);mobile.scrollTop=mobileTop}window.scrollTo({top:y})}
function filterMarkup(){const groups=[['category',t('filterCategory'),data.categories.filter(c=>appList().some(a=>a.categories.includes(c.id))).map(c=>[c.id,c[state.lang]])],['platform',t('platforms'),['Web','iOS','Android','Windows'].filter(p=>appList().some(a=>a.platforms.includes(p))).map(p=>[p,p])],['label',t('filterLabel'),LABELS.filter(l=>appList().some(a=>(a.labels||[]).includes(l.id))).map(l=>[l.id,l[state.lang]])]].filter(([key])=>data.filters[key]);const active=Object.entries(state.multi).flatMap(([key,values])=>values.map(v=>[key,v,key==='category'?catName(v):key==='label'?labelName(v):v]));return '<details class="filter-panel multi-filter-panel" id="filter-panel"'+((state.filtersOpen??false)?' open':'')+'><summary>'+t('filters')+(active.length?'<span class="pill">'+active.length+'</span>':'')+svg('chevron')+'</summary><div class="multi-filter-body">'+groups.map(([key,label,options])=>'<fieldset><legend>'+label+'</legend><div class="filter-checks">'+options.map(([value,name])=>'<label><input type="checkbox" data-multi-filter="'+key+'" value="'+value+'"'+(state.multi[key].includes(value)?' checked':'')+'><span>'+esc(name)+'</span></label>').join('')+'</div></fieldset>').join('')+(data.filters.sort?'<label class="multi-sort">'+t('sortBy')+'<select id="multi-sort">'+[['default','sortDefault'],['az','sortAZ'],['za','sortZA']].map(([v,k])=>'<option value="'+v+'"'+(state.sort===v?' selected':'')+'>'+t(k)+'</option>').join('')+'</select></label>':'')+'<div class="multi-filter-actions"><button class="btn" data-reset-filters>'+t('clearFilters')+'</button><button class="btn primary" data-apply-filters>'+wx('Show results','Sonuçları göster')+'</button></div></div></details>'+(active.length?'<div class="active-filters">'+active.map(([key,value,name])=>'<button data-remove-multi="'+key+'" data-value="'+value+'">'+esc(name)+' ×</button>').join('')+'</div>':'')}
function applyMultiFilters(){const host=$('filter-panel');if(!host)return;for(const key of ['category','platform','label'])state.multi[key]=[...host.querySelectorAll('[data-multi-filter="'+key+'"]:checked')].map(el=>el.value);state.category='all';state.platform='all';state.label='all';state.selected=null;if($('multi-sort'))state.sort=$('multi-sort').value;state.filtersOpen=!isMobile();updateResults()}

const visibleSuggestions=()=>state.query.trim()?data.apps.filter(a=>a.active&&!a.archived&&(local(a).name+' '+local(a).description).toLocaleLowerCase(state.lang).includes(state.query.trim().toLocaleLowerCase(state.lang))).slice(0,5):data.search.ids.map(appById).filter(a=>a?.active&&!a.archived);
function art(a,cls=''){if(a.asset==null&&!a.image)return '<span class="symbol-art" style="background:'+esc(a.color||'#d61530')+'">'+esc(a.symbol||local(a).name.slice(0,2))+'</span>';return a.image?'<img class="art-image '+cls+'" src="'+esc(filePath(a.image))+'" alt="'+esc(local(a).name)+'" loading="lazy">':'<span class="asset '+cls+'" style="--asset-pos:'+([0,33.3333,66.6667,100][a.asset%4])+'% '+(a.asset<4?0:100)+'%" role="img" aria-label="'+esc(local(a).name)+'"></span>'}
function appIcon(a){return '<span class="app-icon">'+art(a)+'</span>'}
function quick(kind,id,label){return isAdmin()?'<button type="button" class="quick" data-edit="'+kind+'"'+(id?' data-id="'+id+'"':'')+' aria-label="'+esc(t(label))+'" title="'+esc(t(label))+'">'+svg('edit')+'</button>':''}
function savePrefs(){prefs={...prefs,lang:state.lang,theme:state.theme,[innerWidth<=680?'layoutMobile':'layoutDesktop']:state.layout};localStorage.setItem('arcelik-review-prefs',JSON.stringify(prefs))}
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3600)}
async function persist(next,action,entity=''){const response=await bridge.request('/api/experience/admin',{data:next,revision:bridge.bootstrap.revision,action,entity:entity||editorContext?.id||editorContext?.kind||''});acceptServer(response);notify(t('saved'))}
function syncAdmins(next){next.admins=[...new Set(next.adminAssignments.map(a=>a.profileId).filter(Boolean))]}
function employeeMatch(id){if(!id)return t('employeeId');const p=PEOPLE.find(p=>p.employeeId===id);return p?t('matchingPerson')+': <b>'+esc(p.name)+'</b>':t('notSignedIn')}
function visibleAdminApps(){return data.apps.filter(a=>(state.adminStatus==='all'||state.adminStatus==='archived'&&a.archived||state.adminStatus==='active'&&!a.archived&&a.active||state.adminStatus==='inactive'&&!a.archived&&!a.active)&&(!state.adminQuery||(local(a).name+' '+a.categories.map(catName).join(' ')).toLocaleLowerCase(state.lang).includes(state.adminQuery.toLocaleLowerCase(state.lang))))}
function applicationsPanel(){return '<div class="section-heading"><h2>'+t('applicationsTitle')+'</h2><button class="btn primary" data-edit="newapp">+ '+t('addApp')+'</button></div><div class="admin-controls"><input id="admin-app-search" type="search" aria-label="'+esc(t('searchApps'))+'" placeholder="'+esc(t('searchApps'))+'" value="'+esc(state.adminQuery)+'"><select id="admin-status" aria-label="'+esc(t('status'))+'">'+[['all','allStatuses'],['active','active'],['inactive','inactive'],['archived','archived']].map(([v,k])=>'<option value="'+v+'"'+(state.adminStatus===v?' selected':'')+'>'+t(k)+'</option>').join('')+'</select></div><div id="admin-app-rows">'+applicationRows()+'</div>'}
function applicationRows(){const list=visibleAdminApps();return '<div class="bulk-tools"><label class="check"><input type="checkbox" id="bulk-all"'+(list.length&&list.every(a=>state.bulk.includes(a.id))?' checked':'')+'> '+t('selectAll')+'</label><span>'+state.bulk.length+' '+t('selectedCount')+'</span>'+(state.bulk.length?'<button class="btn" data-bulk-archive>'+t('archive')+'</button><button class="btn" data-bulk-restore>'+t('restore')+'</button><button class="btn" data-clear-bulk>'+t('clearSelection')+'</button>':'')+'</div>'+list.map(a=>'<div class="admin-row"><input class="bulk-checkbox" type="checkbox" data-bulk-app="'+a.id+'" aria-label="'+esc(t('selectApp')+': '+local(a).name)+'"'+(state.bulk.includes(a.id)?' checked':'')+'>'+appIcon(a)+'<div class="grow"><strong>'+esc(local(a).name)+'</strong><small>'+esc(a.categories.map(catName).join(' · '))+' · v'+esc(a.version)+'</small></div><span class="status '+(a.archived||!a.active?'off':'')+'">'+t(a.archived?'archived':a.active?'active':'inactive')+'</span><div class="row-actions"><button class="btn" data-edit="app" data-id="'+a.id+'">'+t('edit')+'</button><button class="btn" data-toggle-app="'+a.id+'"'+(a.archived?' disabled':'')+'>'+t(a.active?'deactivate':'activate')+'</button><button class="btn" '+(a.archived?'data-restore':'data-archive')+'="'+a.id+'">'+t(a.archived?'restore':'archive')+'</button></div></div>').join('')}
function renderAdminApps(){if($('admin-app-rows'))$('admin-app-rows').innerHTML=applicationRows()}
async function archiveApps(ids,restore){if(!isAdmin()||!ids.length||!confirm(t(restore?'confirmRestore':'confirmArchive')))return;const next=structuredClone(data);for(const a of next.apps)if(ids.includes(a.id))a.archived=!restore;try{await persist(next,'archiveChanged',ids.join(', '));state.bulk=[];if(ids.includes(state.selected)&&!restore)state.selected=null;render()}catch(error){notify(error.message)}}
function categoriesPanel(){return '<h2>'+t('categories')+'</h2><p>'+t('languageScope')+'</p>'+data.categories.map(c=>{const used=data.apps.some(a=>a.categories.includes(c.id));return '<div class="admin-row"><span class="grow"><strong>'+esc(c[state.lang])+'</strong><small>'+data.apps.filter(a=>a.categories.includes(c.id)).length+' '+t('applications')+'</small></span><button class="btn" data-edit="category" data-id="'+c.id+'">'+t('edit')+'</button><button class="btn danger" data-remove-category="'+c.id+'"'+(used?' disabled title="'+esc(t('categoryInUse'))+'"':'')+'>'+t('remove')+'</button></div>'}).join('')+'<button class="btn" data-edit="newcategory">+ '+t('newCategory')+'</button>'}
async function removeCategory(id){if(!isAdmin())return;if(data.apps.some(a=>a.categories.includes(id)))return notify(t('categoryInUse'));if(!confirm(t('confirmRemoveCategory')))return;const next=structuredClone(data);next.categories=next.categories.filter(c=>c.id!==id);try{await persist(next,'categoryRemoved');if(state.category===id)state.category='all';render()}catch(error){notify(error.message)}}
function adminsPanel(){return '<div class="section-heading"><h2>'+t('admins')+'</h2><button class="btn primary" data-edit="newAdmin">+ '+t('addAdmin')+'</button></div><p>'+t('roleHelp')+'</p>'+data.adminAssignments.map(a=>{const p=PEOPLE.find(p=>p.id===a.profileId),own=a.profileId===state.person.id;return '<div class="admin-row"><span class="avatar">'+esc(p?.initials||'?')+'</span><div class="grow"><strong>'+esc(p?.name||t('notSignedIn'))+'</strong><small>'+t('employeeId')+': '+esc(a.employeeId)+'</small></div><div class="row-actions"><button class="btn" data-edit="adminAssignment" data-id="'+esc(a.employeeId)+'"'+(own?' disabled title="'+esc(t('ownAdminProtected'))+'"':'')+'>'+t('edit')+'</button><button class="btn danger" data-revoke-admin="'+esc(a.employeeId)+'"'+(own?' disabled title="'+esc(t('ownAdminProtected'))+'"':'')+'>'+t('revokeAdmin')+'</button></div></div>'}).join('')}
async function revokeAdmin(employeeId){if(!isAdmin())return;const a=data.adminAssignments.find(a=>a.employeeId===employeeId);if(!a)return;if(a.profileId===state.person.id)return notify(t('ownAdminProtected'));if(a.profileId&&data.admins.length<=1)return notify(t('lastAdmin'));if(!confirm(t('confirmRevoke')))return;const next=structuredClone(data);next.adminAssignments=next.adminAssignments.filter(a=>a.employeeId!==employeeId);syncAdmins(next);try{await persist(next,'adminChanged');render()}catch(error){notify(error.message)}}
function translationsPanel(){return '<h2>'+t('translations')+'</h2><p>'+t('translationHelp')+'</p><div class="editing-language">'+t('editingLanguage')+'</div><input id="translation-search" class="mapping-search" type="search" aria-label="'+esc(t('translationSearch'))+'" placeholder="'+esc(t('translationSearch'))+'" value="'+esc(state.translationQuery)+'"><div id="translation-rows">'+translationRows()+'</div>'}
function translationRows(){return Object.keys(TEXT[state.lang]).filter(k=>(k+' '+t(k)).toLocaleLowerCase(state.lang).includes(state.translationQuery.toLocaleLowerCase(state.lang))).map(k=>'<div class="mapping-row"><code>'+esc(k)+'</code><span>'+esc(t(k))+'</span><button class="btn" data-edit="translation" data-id="'+k+'">'+t('edit')+'</button></div>').join('')}
function renderTranslationRows(){if($('translation-rows'))$('translation-rows').innerHTML=translationRows()}
function auditPanel(){return '<h2>'+t('audit')+'</h2><p>'+t('localNote')+'</p>'+(data.audit.length?data.audit.map(e=>'<article class="audit-row"><b>'+esc(t(e.key))+'</b><small>'+esc(e.person)+' · '+new Date(e.time).toLocaleString(state.lang==='tr'?'tr-TR':'en-GB',{timeZone:'Europe/Istanbul'})+'</small>'+(e.entity?'<p>'+esc(e.entity)+'</p>':'')+'<details><summary>'+t('details')+'</summary><pre>'+esc(JSON.stringify(e,null,2))+'</pre></details></article>').join(''):'<p>'+t('auditEmpty')+'</p>')}
function recordActivity(key,entity,outcome=''){bridge.request('/api/experience/event',{key,entity:entity.slice(0,200)}).catch(error=>notify(error.message))}
function activityPanel(){return '<h2>'+t('activity')+'</h2><p>'+t('activityHelp')+'</p>'+(data.activity.length?data.activity.slice(0,200).map(e=>'<article class="audit-row"><b>'+esc(t(e.key))+'</b> · '+esc(e.entity)+'<small>'+esc(e.person)+' · '+new Date(e.time).toLocaleString(state.lang==='tr'?'tr-TR':'en-GB',{timeZone:'Europe/Istanbul'})+(e.outcome?' · '+t(e.outcome):'')+'</small></article>').join(''):'<p>'+t('activityEmpty')+'</p>')}

function featuredSection(){const apps=ordered(data.apps.filter(a=>a.active&&!a.archived&&a.featured),data.uiLayout.featuredOrder);return apps.length?'<section class="featured-section"><div class="featured-title"><h2>'+wx('Recently added','Yeni eklenenler')+'</h2>'+quick('featured',null,'editFeatured')+'</div><div class="feature-bento">'+apps.map((a,i)=>'<button class="bento-card bento-'+(i%4)+'" data-open="'+a.id+'" aria-label="'+esc(t('openDetails')+': '+local(a).name)+'"><span class="bento-copy"><small>'+esc(a.categories.map(catName).slice(0,1).join(''))+'</small><b>'+esc(local(a).name)+'</b><span class="bento-meta"><span class="bento-platform">'+a.platforms.join(' · ')+'</span><span class="bento-inline-arrow" aria-hidden="true">↗</span></span></span><span class="bento-art">'+(a.id==='pa'&&!a.image?'<img src="assets/pa-cutout.png" alt="">':art(a))+'</span></button>').join('')+'</div></section>':''}

function linkLabel(link,a){return link.label?.[state.lang]||((typeof link.label==='string'&&link.label)|| (state.lang==='en'?local(a).name+' for '+link.platform:link.platform+' için '+local(a).name))}
function downloadMarkup(a){const multiple=a.platforms.some(p=>a.links.filter(l=>l.platform===p&&!l.pending&&l.url).length>1);return (multiple?'<p class="release-choice">'+wx('Choose the version that suits your needs.','İhtiyacına uygun sürümü seç.')+'</p>':'')+a.links.map(l=>'<div class="download"><span class="file-type">'+fileType(l.url,l.platform)+'</span><div><b>'+esc(linkLabel(l,a))+'</b><small>'+esc(l.platform)+' · v'+esc(l.version||a.version)+(l.pending||!l.url?' · '+t('pending'):'')+'</small>'+(multiple&&l.notes?.[state.lang]?'<p class="release-note">'+esc(l.notes[state.lang])+'</p>':'')+'</div><button class="btn primary" data-open-resource="'+esc(l.id)+'" data-resource-type="link" data-app="'+a.id+'"'+(l.pending||!l.url?' disabled':'')+'>'+(l.pending||!l.url?t('soon'):l.url.startsWith('apk:')||/\.apk(?:[?#]|$)/i.test(l.url)?wx('Download','İndir'):t('open'))+' ↗</button></div>').join('')}

function fileType(url,platform){const ext=String(url||'').split(/[?#]/)[0].split('.').pop().toUpperCase();return ['APK','IPA','EXE','MSI','PDF','ZIP','DMG'].includes(ext)?ext:platform==='Web'?'Web':platform}
function resourcesMarkup(a){let html='';if(a.images.length)html+='<h3>'+t('screenshots')+'</h3><div class="screenshots-gallery">'+a.images.map((entry,i)=>{const image=typeof entry==='string'?{url:entry}:entry;return '<figure><img src="'+esc(filePath(image.url))+'" loading="lazy" alt="'+esc(image.caption?.[state.lang]||local(a).name+' · '+(i+1))+'">'+(image.caption?.[state.lang]?'<figcaption>'+esc(image.caption[state.lang])+'</figcaption>':'')+'</figure>'}).join('')+'</div>';if(a.documents.length)html+='<h3>'+t('documents')+'</h3>'+a.documents.map(d=>'<div class="download"><span class="file-type">'+fileType(d.url,'PDF')+'</span><div><b>'+esc(d.title?.[state.lang]||d.title?.en||d.title?.tr||t('documents'))+'</b></div><button class="btn" data-open-resource="'+esc(d.id)+'" data-resource-type="document" data-app="'+a.id+'">'+t('open')+' ↗</button></div>').join('');return html}
function openResource(appId,kind,id){window.open(bridge.openPath('app:'+appId,kind,id),'_blank','noopener,noreferrer')}
function safeResource(url,kind){if(kind==='image'&&/^data:image\/(png|jpeg|webp);base64,/.test(url))return true;if(kind==='document'&&/^data:application\/(pdf|msword|vnd\.[a-zA-Z0-9.+-]+|octet-stream);base64,/.test(url))return true;if(/^\/api\/experience\/files\/[0-9a-f-]{36}$/i.test(url))return true;if(kind==='link'&&/^apk:[0-9a-f-]{36}$/i.test(url))return true;if((kind==='document'&&url==='guide.html')||(kind==='image'&&url==='sample-screen.svg'))return true;try{const u=new URL(url);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}
function resourceId(){return 'resource-'+(crypto.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2))}
function assetEditor(a){editorContext.resources={link:{},document:{},image:{}};return '<section class="asset-editor"><h3>'+t('downloadLinks')+'</h3><div id="link-rows">'+a.links.map(l=>resourceRow('link',l)).join('')+'</div><button type="button" class="btn" data-asset-add="link">+ '+t('addLink')+'</button><h3>'+t('documents')+'</h3><div id="document-rows">'+a.documents.map(d=>resourceRow('document',d)).join('')+'</div><button type="button" class="btn" data-asset-add="document">+ '+t('addDocument')+'</button><h3>'+t('screenshots')+'</h3><div id="image-rows">'+a.images.map(i=>resourceRow('image',typeof i==='string'?{url:i}:i)).join('')+'</div><button type="button" class="btn" data-asset-add="image">+ '+t('addScreenshot')+'</button><p class="editor-note muted">'+t('resourceHelp')+'</p></section>'}
function resourceRow(kind,item={}){const id=item.id||resourceId(),lang=editorContext.language;editorContext.resources[kind][id]=structuredClone({...item,id});return '<div class="resource-row compact-link" data-resource-row="link" data-resource-id="'+esc(id)+'"><div class="link-top"><label>'+t('platforms')+'<select name="resourcePlatform">'+['Web','iOS','Android','Windows'].map(p=>'<option'+(p===(item.platform||'Web')?' selected':'')+'>'+p+'</option>').join('')+'</select></label><label>'+t('version')+'<input name="resourceVersion" value="'+esc(item.version||'1.0.0')+'" maxlength="64"></label><button type="button" class="text-remove" data-remove-resource aria-label="'+t('remove')+'">×</button></div><label class="delivery-label">'+wx('Delivery','Edinme şekli')+'<select name="resourceDelivery"><option value="url"'+(!item.url?.startsWith('apk:')?' selected':'')+'>'+wx('Link','Bağlantı')+'</option><option value="apk"'+(item.url?.startsWith('apk:')?' selected':'')+'>APK</option></select></label><label class="field resource-url-field">'+wx('Address','Adres')+'<input name="resourceUrl" value="'+esc(item.url||'')+'" placeholder="https://…"></label><label class="field apk-upload-section"'+(item.url?.startsWith('apk:')?'':' hidden')+'>APK<input type="file" data-apk-upload accept=".apk"><span class="apk-status" role="status"></span></label><label class="check"><input type="checkbox" name="resourcePending"'+(item.pending?' checked':'')+'>'+t('linkPending')+'</label></div>'}
function addAssetRow(kind){if(!editorContext?.resources?.[kind])return;const row=kind==='link'?{platform:'Web',version:'1.0.0',url:'',pending:true,label:{}}:{url:''};$(kind+'-rows').insertAdjacentHTML('beforeend',resourceRow(kind,row));refreshPrivatePreview()}

function updateDelivery(row){const apk=row.querySelector('[name=resourceDelivery]').value==='apk';row.querySelector('.apk-upload-section').hidden=!apk;row.querySelector('.resource-url-field').hidden=apk;if(apk){row.querySelector('[name=resourcePlatform]').value='Android';const android=document.querySelector('#editor-form [name=platforms][value=Android]');if(android)android.checked=true}else if(row.querySelector('[name=resourceUrl]').value.startsWith('apk:')){row.querySelector('[name=resourceUrl]').value='';row.querySelector('[name=resourcePending]').checked=true}}
function readAssets(form,lang){const result={links:[],documents:structuredClone(editorContext.originalApp?.documents||[]),images:structuredClone(editorContext.originalApp?.images||[])};for(const row of form.querySelectorAll('[data-resource-row]')){const id=row.dataset.resourceId,previous=editorContext.resources.link[id]||{},url=row.querySelector('[name=resourceUrl]').value.trim(),platform=row.querySelector('[name=resourcePlatform]').value,version=row.querySelector('[name=resourceVersion]').value.trim(),pending=row.querySelector('[name=resourcePending]').checked;if(!version||(!pending&&!url)||(url&&!safeResource(url,'link')))throw Error(t('linksRequired'));const labels=typeof previous.label==='string'?{en:previous.label,tr:previous.label}:previous.label||{};result.links.push({...previous,id,url,platform,version,pending,label:{...labels,[lang]:labels[lang]||form.elements.namedItem('name').value+' · '+platform}})}const removed=editorContext.removedFiles||[];result.documents=result.documents.filter(d=>!removed.includes(d.id));result.images=result.images.filter((d,i)=>!removed.includes(d.id||'old-image-'+i));for(const file of editorContext.uploads||[]){if(file.type.startsWith('image/')){if(!result.images.some(r=>r.id===file.id))result.images.push({id:file.id,url:file.url,caption:{[lang]:file.name}})}else if(!result.documents.some(r=>r.id===file.id))result.documents.push({id:file.id,url:file.url,title:{[lang]:file.name}})}return result}
function privateCard(a){return '<article class="private-card compact-card"><div class="card-open"><span class="short-logo">'+art(a)+'</span><span class="short-info"><h3>'+esc(local(a).name)+'</h3>'+labelsMarkup(a)+'</span></div></article>'}
function refreshPrivatePreview(){const f=$('editor-form'),preview=$('private-card');if(!f||!preview||!['app','newapp'].includes(editorContext?.kind))return;const original=appById(editorContext.id)||{id:'draft',en:{},tr:{},labels:[],comments:[],asset:null,image:'',color:'#d61530'},a=structuredClone(original),lang=editorContext.language;a[lang]={...a[lang],name:f.elements.namedItem('name')?.value||'',summary:f.elements.namedItem('description')?.value||'',description:f.elements.namedItem('description')?.value||''};a.version=f.elements.namedItem('version')?.value||'';a.featuredComment=f.elements.namedItem('featuredComment')?.value||null;a.platforms=[...f.querySelectorAll('[name=platforms]:checked')].map(e=>e.value);a.categories=[...f.querySelectorAll('[name=categories]:checked')].map(e=>e.value);a.labels=[...f.querySelectorAll('[name=labels]:checked')].map(e=>e.value);a.color=f.elements.namedItem('color')?.value||a.color;a.symbol=f.elements.namedItem('symbol')?.value||a.symbol;if(editorContext.imagePreview)a.image=editorContext.imagePreview;preview.innerHTML=privateCard(a)}
function dismissMenus(target){if(state.account&&!target.closest('.account-pop,#account-toggle')){state.account=false;document.querySelector('.account-pop')?.remove();$('account-toggle')?.setAttribute('aria-expanded','false')}if(state.expanded&&!target.closest('.categorynav')){state.expanded=null;document.querySelectorAll('.categoryapps').forEach(e=>e.hidden=true);document.querySelectorAll('.category-expand').forEach(e=>e.setAttribute('aria-expanded','false'))}if(!target.closest('.search-wrap'))hideSuggestions()}
onDocument('pointerdown',e=>dismissMenus(e.target));
onDocument('click',async e=>{if(!$('editDialog').open&&!$('mobileDetail').open&&state.selected&&!e.target.closest('button,a,input,select,textarea,label,summary,.detail-pane,.appcard,.featured-card,.categorynav,.filter-panel,.search-wrap,.active-filters,.account-pop'))closeDetail()});
for(const [id,close] of [['editDialog',()=>closeEditor()],['mobileDetail',()=>closeDetail()]])$(id).addEventListener('click',e=>{if(e.target!==$(id))return;e.stopPropagation();close()});
$('mobileDetail').addEventListener('cancel',e=>{e.preventDefault();closeDetail()});
onDocument('keydown',e=>{if(e.key!=='Escape'||$('editDialog').open||$('mobileDetail').open||e.target.id==='search')return;if(state.account||state.expanded){dismissMenus(document.body);return}if(state.selected)closeDetail()});

function environmentLabel(){return bridge.bootstrap.environment==='Test'?'<span class="env">TEST</span>':''}
function mobileHeader(){return '<header class="topbar page-width mobile-topbar '+(state.mobileMenu?'mobile-menu-open':'')+'"><button class="mobile-menu-button" data-mobile-menu aria-expanded="'+!!state.mobileMenu+'" aria-label="'+wx(state.mobileMenu?'Close menu':'Menu',state.mobileMenu?'Menüyü kapat':'Menü')+'">'+(state.mobileMenu?'×':'☰')+'</button><div class="mobile-menu-sheet"><button class="brand" data-home aria-label="'+t('store')+'">'+(data.logo?'<img src="'+esc(filePath(data.logo))+'" alt="Arçelik">':'<span class="brand-wordmark" role="img" aria-label="Arçelik"></span>')+'<span class="brand-title">'+t('store')+'</span></button><div class="mobile-menu-profile"><span class="avatar">'+esc(state.person.initials)+'</span><b>'+esc(state.person.name)+'</b>'+environmentLabel()+'</div><div class="mobile-menu-preferences"><button class="mobile-menu-action" data-theme>'+svg('moon')+t('themeLabel')+' · '+t(state.theme)+'</button><button class="mobile-menu-action" data-lang>'+t('language')+' · '+state.lang.toUpperCase()+'</button></div><button class="mobile-menu-action" data-help>'+wx('Suggestions & complaints','Öneri ve şikayet')+' ↗</button></div></header>'}

function previewAccounts(){if(bridge.bootstrap.environment!=='Test')return '';return '<details class="account-profiles"'+(bridge.bootstrap.environment!=='Test'?' hidden':'')+(previewPeople().length<=3?' open':'')+'><summary>'+t('rolePreview')+'</summary>'+previewPeople().map(p=>'<button class="person" data-person="'+p.id+'"><span class="avatar">'+esc(p.initials)+'</span><span>'+esc(p.name)+'<small>'+t(p.synthetic?(p.testRole==='admin'?'admin':'employee'):(data.admins.includes(p.id)?'admin':'employee'))+'</small></span>'+(state.person.id===p.id?'✓':'')+'</button>').join('')+'</details>';}
function header(){if(innerWidth<900)return mobileHeader();return '<header class="topbar page-width '+(state.mobileMenu?'mobile-menu-open':'')+'"><button class="brand" data-home aria-label="'+esc(t('back'))+'">'+(data.logo?'<img src="'+esc(filePath(data.logo))+'" alt="Arçelik">':'<span class="brand-wordmark" role="img" aria-label="Arçelik"></span>')+'<span class="brand-title">'+t('store')+'</span></button>'+environmentLabel()+''+quick('logo',null,'editLogo')+'<button class="mobile-menu-button" data-mobile-menu aria-expanded="'+!!state.mobileMenu+'" aria-label="'+wx('Menu','Menü')+'">☰</button><div class="tools">'+(isAdmin()?'<button class="btn primary manage-button" data-manage aria-label="'+esc(t('manage'))+'">'+svg('gear')+'<span class="manage-label">'+t('manage')+'</span></button>':'')+'<button class="icon-btn theme-button" data-theme aria-label="'+esc(t('theme'))+'">'+svg('moon')+'</button><button class="icon-btn" data-lang aria-label="'+esc(t('language'))+'">'+state.lang.toUpperCase()+'</button><button class="account" id="account-toggle" data-account aria-expanded="'+state.account+'" aria-label="'+esc(t('account'))+'"><span class="avatar">'+state.person.initials+'</span><span class="name">'+state.person.name+'</span></button></div></header>'+(state.account?'<div class="account-pop"><div class="account-intro"><b>'+esc(state.person.name)+'</b><small>'+t(isAdmin()?'admin':'employee')+'</small></div>'+previewAccounts()+''+testLocationMarkup()+'<button class="account-help" data-help>✧ '+wx('Suggestions & complaints','Öneri ve şikayet')+' ↗</button><button class="btn" data-theme>'+svg('moon')+t('themeLabel')+' · '+t(state.theme)+'</button>'+'</div>':'')}
function searchMarkup(){return '<div class="search-wrap">'+quick('search',null,'editSearch')+'<form id="search-form" class="search-box" role="search"><svg viewBox="0 0 24 24" aria-hidden="true">'+icons.search+'</svg><input id="search" type="search" autocomplete="off" maxlength="200" aria-label="'+esc(t('search'))+'" placeholder="'+esc(searchPlaceholder())+'" value="'+esc(state.query)+'" role="combobox" aria-expanded="false" aria-controls="search-pop" aria-autocomplete="list"><button type="submit" class="icon-btn" aria-label="'+esc(t('search'))+'">'+svg('arrow')+'</button></form><div id="search-pop" class="search-pop" role="listbox" hidden></div></div>'}
function searchPlaceholder(){const featured=data.search.ids.map(appById).filter(a=>a?.active&&!a.archived);return featured.length?(data.search[state.lang]||t('searchExamples'))+' '+local(featured[state.rotation%featured.length]).name:t('search')}
function categoryMarkup(){const apps=appList();return '<aside class="categorynav"><div class="categorytitle"><h3>'+t('categories')+'</h3>'+quick('categories',null,'editCategory')+'</div><div class="category-list">'+[{id:'all'},...data.categories.filter(c=>apps.some(a=>a.categories.includes(c.id)))].map(c=>{const list=c.id==='all'?apps:apps.filter(a=>a.categories.includes(c.id));const expanded=state.expanded===c.id;return '<section class="categoryitem '+((c.id==='all'?!state.multi.category.length:state.multi.category.includes(c.id))?'active':'')+'"><div class="categoryrow"><button class="category-button" data-category="'+c.id+'" aria-pressed="'+((c.id==='all'?!state.multi.category.length:state.multi.category.includes(c.id)))+'"><span class="category-dot"></span><span class="name">'+esc(c.id==='all'?t('all'):catName(c.id))+'</span><span class="pill">'+list.length+'</span></button><button class="category-expand" data-expand="'+c.id+'" aria-expanded="'+expanded+'" aria-label="'+esc(t(expanded?'collapseCategory':'expandCategory'))+'">'+svg('chevron')+'</button></div><div class="categoryapps"'+(expanded?'':' hidden')+'>'+list.map(a=>'<button class="category-app" data-open="'+a.id+'">'+appIcon(a)+'<span>'+esc(local(a).name)+'</span></button>').join('')+'</div></section>'}).join('')+'</div></aside>'}
function cardMarkup(a){return '<article class="appcard compact-card '+(state.selected===a.id?'selected':'')+'"><button class="card-open" data-open="'+a.id+'" aria-label="'+esc(local(a).name)+'"><span class="short-logo">'+art(a)+'</span><span class="short-info"><h3>'+esc(local(a).name)+'</h3>'+labelsMarkup(a)+'</span></button><div class="short-tools">'+socialButtons('app:'+a.id)+quick('app',a.id,'editApp')+'</div></article>'}
function detailMarkup(a,mobile=false){return '<div class="detail-content concise-detail"><div class="detail-heading">'+appIcon(a)+'<div><h2>'+esc(local(a).name)+'</h2><span class="detail-platforms">'+a.platforms.join(' · ')+(a.version?' · v'+esc(a.version):'')+'</span></div><button class="icon-btn" data-close-detail aria-label="'+t('close')+'">'+svg('close')+'</button></div><p class="concise-summary">'+esc((local(a).description||local(a).summary).slice(0,150))+'</p>'+labelsMarkup(a)+'<section class="concise-downloads"><h3>'+t('getApp')+'</h3>'+downloadMarkup(a)+'</section><div class="detail-secondary">'+resourcesMarkup(a)+''+(a.platforms.every(p=>p==='Web')?'':'<details><summary>'+t('comments')+' · '+a.comments.length+'</summary>'+commentsMarkup(a)+'</details>')+'</div><div class="detail-bottom">'+(isAdmin()?'<button class="btn" data-edit="app" data-id="'+a.id+'">'+svg('edit')+t('editApp')+'</button>':'')+'</div></div>'}

