Object.assign(state,{webQuery:'',webGroup:'all',webLimit:8});
function myItems(){return personal[state.person.id]??={favorites:[],likes:[]}}
function socialButtons(id){const mine=myItems();const glyph=(key,selected)=>'<svg viewBox="0 0 24 24" aria-hidden="true" fill="'+(selected?'currentColor':'none')+'" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">'+(key==='likes'?'<path d="M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z"/>':'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9L12 3Z"/>')+'</svg>';return '<div class="social-actions">'+[['favorites',wx('Save to favourites','Favorilere ekle')]].map(([key,label])=>'<button type="button" data-social="'+key+'" data-social-id="'+esc(id)+'" aria-pressed="'+mine[key].includes(id)+'" aria-label="'+label+'" title="'+label+'">'+glyph(key,mine[key].includes(id))+'</button>').join('')+'</div>'}
