function favoriteRecords(){return [...data.apps.filter(a=>a.active&&!a.archived).map(a=>({id:'app:'+a.id,name:local(a).name,kind:a.platforms.every(p=>p==='Web')?'web':'app',app:a.id,record:a})),...data.webEntries.filter(visibleWeb).map(r=>({id:'web:'+r.id,name:r[state.lang].name,kind:'web',url:r.url,record:r})),{id:'web:behome',name:data.webPortal[state.lang].name,kind:'portal',url:data.webPortal.url,record:data.webPortal}].filter(r=>myItems().favorites.includes(r.id))}
function favoriteLogo(r){return r.app?art(r.record):r.record.image?'<img src="'+esc(r.record.image)+'" alt="">':'<span class="favorite-monogram">'+esc(r.record.symbol||r.name.slice(0,1))+'</span>'}
function favoritesMarkup(){const records=favoriteRecords();return '<aside class="favorites-section '+(state.favoritesOpen?'favorites-open':'')+'" id="personal-favourites" aria-label="'+wx('Favourites','Favoriler')+'"><button class="favorites-toggle" data-favorites-toggle aria-expanded="'+!!state.favoritesOpen+'"><span class="stack-preview" aria-hidden="true">'+(records.length?records.slice(0,3).map(r=>'<i>'+favoriteLogo(r)+'</i>').join(''):'<i>☆</i>')+'</span><span class="stack-title">'+wx('Favourites','Favoriler')+'</span><span class="stack-count">'+records.length+'</span></button><div class="favorite-heading"><h2>☆ '+wx('Your favourites','Favorilerin')+'</h2><span>'+records.length+'</span></div>'+(records.length?'<div class="favorite-strip">'+records.map((r,i)=>'<div class="favorite-item" style="--favorite-hue:'+((i*47+190)%360)+'">'+(r.app&&r.kind==='app'?'<button class="favorite-launch" data-open="'+r.app+'" title="'+esc(r.name)+'">':'<a class="favorite-launch" title="'+esc(r.name)+'" target="_blank" rel="noopener noreferrer" href="'+esc(r.url||appById(r.app)?.url||'https://connecta.beko.com')+'">')+'<span class="favorite-orb">'+favoriteLogo(r)+'<span class="orb-arrow">↗</span></span><b>'+esc(r.name)+'</b>'+(r.app&&r.kind==='app'?'</button>':'</a>')+'<button class="favorite-remove" data-social="favorites" data-social-id="'+r.id+'" aria-label="'+wx('Remove favourite','Favorilerden çıkar')+'">×</button></div>').join('')+'</div>':'<p class="favorite-empty">'+wx('Keep your everyday tools here. Tap ☆ on a card to save it.','Günlük araçların burada elinin altında olsun. Karttaki ☆ ile favorilerine ekle.')+'</p>')+'<small class="personal-note">'+wx('Your personal selections','Sana özel seçimler')+'</small></aside>'}


