function portalCard(r){return '<article class="portal-photo-card" style="--portal-bg:url(&quot;'+esc(r.background||'assets/portal-office.jpg')+'&quot;)"><a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer"><span class="portal-card-kicker">'+wx('COMPANY PORTAL','ŞİRKET PORTALI')+'</span><span class="portal-card-copy"><h2>'+esc(r[state.lang].name)+'</h2><p>'+esc(r[state.lang].description)+'</p><span class="portal-open">'+wx('Open portal','Portalı aç')+' ↗</span></span></a>'+quick('webEntry',r.id,'edit')+socialButtons('web:'+r.id)+'</article>'}
function setupWebWizard(){const form=$('editor-form');if(!form)return;form.dataset.webWizard='true';form.dataset.step='0';const steps=[...form.querySelectorAll('[data-web-step]')];let current=0;const nav=document.createElement('div');nav.className='web-wizard-nav';form.querySelector('.dialog-body').prepend(nav);const move=n=>{current=n;form.dataset.step=n;steps.forEach((el,i)=>el.hidden=innerWidth<=680&&i!==n);nav.innerHTML=[0,1,2].map((i)=>'<span class="'+(i===n?'current':'')+'">'+(i+1)+' · '+[wx('Type','Tür'),wx('Content','İçerik'),wx('Link & image','Bağlantı ve görsel')][i]+'</span>').join('');form.querySelector('[type=submit]').hidden=innerWidth<=680&&n<2;let controls=form.querySelector('.wizard-buttons');if(!controls){controls=document.createElement('div');controls.className='wizard-buttons';form.querySelector('.dialog-actions').prepend(controls)}controls.innerHTML=innerWidth<=680?(n>0?'<button type="button" class="btn" data-wizard-back>'+wx('Back','Geri')+'</button>':'')+(n<2?'<button type="button" class="btn primary" data-wizard-next>'+wx('Continue','Devam')+' →</button>':''):'';};form.addEventListener('click',e=>{if(e.target.closest('[data-wizard-back]'))move(Math.max(0,current-1));if(e.target.closest('[data-wizard-next]')){const invalid=[...steps[current].querySelectorAll('[required]')].find(el=>!el.value.trim());if(invalid){invalid.focus();return}move(Math.min(2,current+1))}});form.addEventListener('change',e=>{if(innerWidth<=680&&e.target.name==='webScope')move(1)});move(0)}
function webEntry(id){return id==='connecta'?appById('connecta'):id==='behome'?data.webPortal:data.webEntries.find(r=>r.id===id)}
function webCard(r,i){const c=r[state.lang],via=r.url==='https://arcelik.sharepoint.com/sites/BeHome';return '<article class="web-tool-shell" data-web-name="'+esc((c.name+' '+c.description).toLocaleLowerCase())+'"><a class="web-tool" href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">'+(r.image?'<img class="tool-image" src="'+esc(filePath(r.image))+'" alt="">':'<span class="tool-monogram" style="--tool-color:'+['#00879b','#7555be','#0078ba','#d17a12','#237a52'][i%5]+'">'+esc(r.symbol)+'</span>')+'<div><h3>'+esc(c.name)+'</h3><p>'+esc(c.description)+'</p><small>'+wx(r.type==='webapp'?'WEB APPLICATION':via?'Via BeHome':'CONNECTED SERVICE',r.type==='webapp'?'WEB UYGULAMASI':via?'BeHome üzerinden':'BAĞLANTILI HİZMET')+' ↗</small></div></a>'+quick('webEntry',r.id,'edit')+socialButtons('web:'+r.id)+'</article>'}

