function promoCopy(){return data.copy[state.lang]}
onDocument('click',async e=>{if(e.target.id==='helpDialog')e.target.close()});
function openHelp(){const d=$('helpDialog');d.innerHTML='<div class="dialog-head"><h2>'+wx('Suggestions & complaints','Öneri ve şikayet')+'</h2><button class="icon-btn" data-help-close aria-label="'+t('close')+'">×</button></div><div class="dialog-body"><p class="web-note">'+wx('Send suggestions, complaints or application needs to your administrators.','Öneri, şikayet ve uygulama ihtiyaçlarını yöneticilerine ilet.')+'</p><label class="field">'+wx('Topic','Konu')+'<select id="feedback-topic"><option>'+wx('Suggestion','Öneri')+'</option><option>'+wx('Application idea / need','Uygulama fikri / ihtiyaç')+'</option><option>'+wx('Complaint','Şikayet')+'</option></select></label><label class="field">'+wx('Message','Mesaj')+'<textarea id="feedback-message" rows="4" maxlength="2000"></textarea></label><p id="feedback-status" class="web-note" role="status"></p><button class="btn primary" data-feedback-save>'+wx('Send','Gönder')+'</button><button class="btn" data-help-close>'+t('close')+'</button></div>';try{const draft=JSON.parse(localStorage.getItem('arcelik-feedback-draft-'+state.person.id)||'null');if(draft){$('feedback-message').value=draft.message||'';const options=[...$('feedback-topic').options];if(options.some(o=>o.value===draft.topic))$('feedback-topic').value=draft.topic}}catch{}d.showModal()}


onDocument('click',e=>{const anchor=e.target.closest('a[target="_blank"]');if(!anchor)return;const href=anchor.getAttribute('href');const web=data.webEntries.find(r=>r.url===href);const app=data.apps.find(a=>a.url===href);const resource=app?'app:'+app.id:web?'web:'+web.id:href===data.webPortal.url?'web:behome':null;if(resource){e.preventDefault();window.open(bridge.openPath(resource),'_blank','noopener,noreferrer')}});
