onDocument('input',e=>{if(e.target.name==='employeeId'&&$('employee-match'))$('employee-match').innerHTML=employeeMatch(e.target.value.trim());if(e.target.closest('#editor-form')&&['app','newapp'].includes(editorContext?.kind))refreshPrivatePreview();if(e.target.id==='admin-app-search'){state.adminQuery=e.target.value;renderAdminApps();return}if(e.target.id==='translation-search'){state.translationQuery=e.target.value;renderTranslationRows();return}if(e.target.hasAttribute('data-comment')){state.commentDrafts[e.target.dataset.comment]={text:e.target.value,language:state.lang};const count=e.target.closest('form').querySelector('.comment-counter');if(count)count.textContent=e.target.value.length+'/300';return}if(e.target.id==='search'){state.query=e.target.value;state.suggestionIndex=-1;updateResults();showSuggestions()}});
