onDocument('change',async e=>{if(e.target.id==='admin-status'){state.adminStatus=e.target.value;renderAdminApps();return}if(e.target.id==='bulk-all'){for(const a of visibleAdminApps()){if(e.target.checked&&!state.bulk.includes(a.id))state.bulk.push(a.id);else if(!e.target.checked)state.bulk=state.bulk.filter(id=>id!==a.id)}renderAdminApps();return}if(e.target.matches('[data-bulk-app]')){const id=e.target.dataset.bulkApp;state.bulk=e.target.checked?[...new Set([...state.bulk,id])]:state.bulk.filter(x=>x!==id);renderAdminApps();return}if(e.target.closest('#editor-form')&&['app','newapp'].includes(editorContext?.kind)&&e.target.type!=='file')refreshPrivatePreview();if(['platform','category-filter','label-filter','sort-filter'].includes(e.target.id)){const key={platform:'platform','category-filter':'category','label-filter':'label','sort-filter':'sort'}[e.target.id];state[key]=e.target.value;state.selected=null;const focusId=e.target.id;render();$(focusId)?.focus({preventScroll:true})}if(e.target.type==='file'&&$('upload-preview')){try{const src=await readFile(e.target.files[0]);if(src){$('upload-preview').src=src;$('upload-preview').hidden=false;if(editorContext)editorContext.imagePreview=src;refreshPrivatePreview()}}catch(error){e.target.value='';if(editorContext)editorContext.imagePreview=null;if($('upload-preview'))$('upload-preview').hidden=true;refreshPrivatePreview();$('form-error').textContent=error.message;$('form-error').hidden=false}}});
